// TypeScript Version: 4.1

/**
* Immutably inserts a value into an array at a path in a document using structural sharing.
*
* @param document - source document
* @param tokens - array of reference tokens
* @param value - value to insert
* @throws tokens must not be empty
* @throws tokens must not contain unsafe tokens
* @throws intermediate path segments must reference objects or arrays
* @throws target container must be an array
* @throws array index must be within bounds
* @returns new document with the value inserted
*
* @example
* var doc = {
*     'a': [ 1, 2, 3 ]
* };
* var out = insert( doc, [ 'a', '1' ], 99 );
* // returns { 'a': [ 1, 99, 2, 3 ] }
*
* var bool = ( doc.a === out.a );
* // returns false
*
* bool = ( doc === out );
* // returns false
*/
declare function insert( document: Array<any> | Record<string, any>, tokens: Array<string>, value: any ): any;


// EXPORTS //

export = insert;
